using System.Security.Claims;
using System.Text.Json.Nodes;
using Npgsql;
using TWM.API.Models;
using static TWM.API.Services.StateService;
namespace TWM.API.Services;
public sealed class CommerceService(DatabaseService database,StateService state){
 sealed record Plan(string Seller,int? AddressId,JsonArray Lines,decimal Width,decimal Height,decimal Depth,decimal Weight,bool FixedShipping,JsonObject Totals);
 async Task<Plan> Calculate(NpgsqlConnection c,NpgsqlTransaction? tx,CheckoutRequest request,ClaimsPrincipal user,CancellationToken ct){
  if(!user.IsInRole("Cliente"))throw new ForbiddenException();
  var rut=Rut(user);if(request.Items.Count is <1 or >100||request.DeliveryMode is not ("Despacho" or "Retiro"))throw new ArgumentException("Compra inválida.");var client=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('age',extract(year from age(CURRENT_DATE,fechanac)))::text FROM public.cliente WHERE run=@rut",ct,("rut",rut));if(client.Count==0)throw new ArgumentException("Esta cuenta necesita un perfil de cliente para comprar.");
  int? addressId=null;if(request.Address!=null&&int.TryParse(Text(request.Address,"id"),out var aid)){var found=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('id',direccion_id)::text FROM public.registrar WHERE cliente_id=@rut AND direccion_id=@id",ct,("rut",rut),("id",aid));if(found.Count>0)addressId=aid;}if(request.DeliveryMode=="Despacho"&&addressId==null)throw new ArgumentException("Selecciona una dirección real de tu cuenta.");
  string? seller=null;var lines=new JsonArray();decimal netBase=0,width=0,height=0,depth=0,weight=0;
  foreach(var line in request.Items){var parts=Id(line).Split('-');if(parts.Length<4||parts[0] is not ("P" or "S")||!int.TryParse(parts[1],out var item))throw new ArgumentException("El artículo no pertenece al catálogo cargado.");var owner=string.Join('-',parts.Skip(2));var retired=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('id',id)::text FROM shopping_ui.listing_state WHERE id=@id AND NOT active",ct,("id",Id(line)));if(retired.Count>0)throw new ArgumentException("La publicación fue retirada por el vendedor.");seller??=owner;if(owner!=seller)throw new ArgumentException("Cada compra corresponde a un vendedor.");var qty=Number(line,"qty");if(qty<1||qty%1!=0||qty>100000)throw new ArgumentException("Cantidad inválida.");var service=parts[0]=="S";JsonArray found;int variant=0;
   if(service)found=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('net',fn_precio_servicio(s.id,o.emprendedor_id),'age',s.edadminima,'mode',s.descripcion->>'Modalidad','name',s.nombre,'seller',coalesce(e.nombre,r.nombre||' '||r.apellido))::text FROM public.servicio s JOIN public.ofrecers o ON o.servicio_id=s.id JOIN public.emprendedor r ON r.run=o.emprendedor_id LEFT JOIN public.empresa e ON e.rut=r.empresa_id WHERE s.id=@id AND o.emprendedor_id=@seller AND s.activo AND NOT s.ocultoporinactividad",ct,("id",item),("seller",owner));
   else{if(!int.TryParse(Text(line,"sku"),out variant))throw new ArgumentException("Selecciona una variante real.");found=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('net',fn_precio_producto(p.id,o.emprendedor_id,o.caracteristicas_id),'age',p.edadminima,'stock',o.stock,'width',p.descripción->'Ancho','height',p.descripción->'Alto','depth',p.descripción->'Fondo','weight',ch.peso,'name',p.nombre,'seller',coalesce(e.nombre,r.nombre||' '||r.apellido))::text FROM public.producto p JOIN public.ofrecerp o ON o.producto_id=p.id JOIN public.caracteristicas ch ON ch.id=o.caracteristicas_id JOIN public.emprendedor r ON r.run=o.emprendedor_id LEFT JOIN public.empresa e ON e.rut=r.empresa_id WHERE p.id=@id AND o.emprendedor_id=@seller AND o.caracteristicas_id=@variant AND p.activo AND NOT p.ocultoporinactividad",ct,("id",item),("seller",owner),("variant",variant));}
   var product=found.FirstOrDefault()??throw new ArgumentException("Artículo no disponible.");if(product["net"]==null)throw new ArgumentException("La oferta del vendedor no está vigente.");if(Text(product,"seller")!=request.Vendor)throw new ArgumentException("El vendedor seleccionado cambió.");if(Number(client[0],"age")<Number(product,"age"))throw new ArgumentException("No cumples la edad mínima del artículo.");if(service&&Text(product,"mode")=="Presencial"&&addressId==null)throw new ArgumentException("El servicio presencial requiere una dirección de tu cuenta.");
   var needed=request.Items.Where(x=>Id(x)==Id(line)&&Text(x,"sku")==Text(line,"sku")).Sum(x=>Number(x,"qty"));if(!service&&Number(product,"stock")<needed)throw new ArgumentException("Stock insuficiente.");
   var price=Number(product,"net");if(Text(line,"quoteId")!=""){
    var quoted=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('net',(d->>'precio_unitario')::numeric,'qty',(d->>'cantidad')::int)::text FROM public.cotizacion q CROSS JOIN LATERAL jsonb_array_elements(q.detalle) d WHERE q.id=@quote AND q.cliente_id=@rut AND q.emprendedor_id=@seller AND q.estado='Aceptada por el cliente' AND CURRENT_DATE<=q.fecha+15 AND ((@service AND (d->>'servicio_id')::int=@item) OR (NOT @service AND (d->>'producto_id')::int=@item AND (d->>'caracteristicas_id')::int=@variant)) AND NOT EXISTS(SELECT 1 FROM shopping_ui.used_quotes u WHERE u.quote_id=q.id)",ct,("quote",int.Parse(Text(line,"quoteId"))),("rut",rut),("seller",owner),("item",item),("variant",variant),("service",service));if(quoted.Count==0||needed>Number(quoted[0],"qty"))throw new ArgumentException("Cotización inválida, utilizada o vencida.");price=Number(quoted[0],"net");
   }
   if(RelationalStore.Gross(price)!=Number(line,"price"))throw new ArgumentException("El precio cambió. Actualiza el carrito.");netBase+=price*qty;if(!service){width=Math.Max(width,Number(product,"width"));depth=Math.Max(depth,Number(product,"depth"));height+=Number(product,"height")*qty;weight+=Number(product,"weight")*qty;}
   lines.Add(new JsonObject{["id"]=Id(line),["type"]=service?"Servicio":"Producto",["dbId"]=item,["variant"]=variant,["qty"]=qty,["net"]=price,["quoteId"]=Text(line,"quoteId")});
  }
  var discounts=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('frequent',count(*) FILTER(WHERE fecha>=date_trunc('month',CURRENT_DATE))>5,'inactive',max(fecha) IS NOT NULL AND CURRENT_DATE BETWEEN (max(fecha)+interval '6 months')::date AND (max(fecha)+interval '6 months 45 days')::date)::text FROM public.venta WHERE cliente_id=@rut AND estado IN ('Entregado','Recibido')",ct,("rut",rut));var percent=discounts[0]?["frequent"]?.GetValue<bool>()==true?10:discounts[0]?["inactive"]?.GetValue<bool>()==true?5:0;var discount=Math.Round(netBase*percent/100m,MidpointRounding.AwayFromZero);var net=netBase-discount;var iva=Math.Round(net*.19m,MidpointRounding.AwayFromZero);var shipping=request.DeliveryMode=="Despacho"&&width>0&&depth>0&&height>0?Math.Round(2000+width*depth*height*.25m,MidpointRounding.AwayFromZero):0;
  var fixedShipping=false;
  var custom=await RelationalStore.Query(c,tx,"SELECT payload::text FROM shopping_ui.documents WHERE id='global:zones'",ct);
  var method=await RelationalStore.Query(c,tx,"SELECT payload::text FROM shopping_ui.documents WHERE id=@id",ct,("id",Key("shippingMethod",seller!)));
  if(request.DeliveryMode=="Despacho"&&method.FirstOrDefault()?.ToString()=="zona"&&addressId!=null){var destination=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('comuna',co.nombre)::text FROM public.direccion d JOIN public.comuna co ON co.id=d.comuna_id WHERE d.id=@id",ct,("id",addressId.Value));var zone=Rows(custom.FirstOrDefault()).FirstOrDefault(z=>Text(z,"ownerRut")==seller&&Text(z,"comuna")==Text(destination.FirstOrDefault(),"comuna"));if(zone==null)throw new ArgumentException("El vendedor no tiene una tarifa para esta comuna.");shipping=Number(zone,"rate");fixedShipping=true;}
  return new(seller!,addressId,lines,width,height,depth,weight,fixedShipping,new(){["subtotal"]=RelationalStore.Gross(netBase),["discount"]=RelationalStore.Gross(netBase)-net-iva,["net"]=net,["iva"]=iva,["shipping"]=shipping,["total"]=net+iva+shipping});
 }
 public async Task<object> Preview(CheckoutRequest request,ClaimsPrincipal user,CancellationToken ct){await using var c=await database.Open(ct);var p=await Calculate(c,null,request,user,ct);return p.Totals;}
 public async Task<object> Checkout(CheckoutRequest request,ClaimsPrincipal user,CancellationToken ct){if(!Guid.TryParse(request.RequestId,out _))throw new ArgumentException("Identificador de operación inválido.");var rut=Rut(user);await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await state.Lock(c,tx,ct);var existing=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('id',order_id)::text FROM shopping_ui.checkout_requests WHERE owner=@rut AND request_id=@request",ct,("rut",rut),("request",request.RequestId));
  if(existing.Count>0){var snapshot=await state.Load(c,tx,ct);return new{order=List(snapshot,"orders").FirstOrDefault(o=>Id(o)==Id(existing[0]))?.DeepClone(),state=state.Snapshot(snapshot,await state.Revision(c,tx,ct),user)};}
  var plan=await Calculate(c,tx,request,user,ct);if(request.Payment is not ("Tarjeta" or "Transferencia")||request.Payment=="Tarjeta"&&!System.Text.RegularExpressions.Regex.IsMatch(request.CardLast4??"",@"^\d{4}$")||request.Payment=="Transferencia"&&(request.TransferCode??"").Length is <5 or >80)throw new ArgumentException("Medio de pago inválido.");
  var quotes=plan.Lines.Select(x=>Text(x,"quoteId")).Where(x=>x!="").Distinct().ToArray();if(quotes.Length>1)throw new ArgumentException("Usa una cotización por compra.");if(quotes.Length==1)await RelationalStore.Exec(c,tx,"SELECT set_config('shopping.quote_id',@quote,true)",ct,("quote",quotes[0]));
  int? shippingId=null;if(request.DeliveryMode=="Despacho"&&(Number(plan.Totals,"shipping")>0||plan.FixedShipping)){shippingId=await RelationalStore.Next(c,tx,"envio","seguimiento",ct);await RelationalStore.Exec(c,tx,plan.FixedShipping?"INSERT INTO public.envio(seguimiento,cliente_id,direccion_id,empresa,valor) VALUES(@id,@rut,@address,'Por asignar',@fee)":"INSERT INTO public.envio(seguimiento,cliente_id,direccion_id,empresa,peso,altura,ancho,fondo) VALUES(@id,@rut,@address,'Por asignar',@weight,@height,@width,@depth)",ct,("fee",Number(plan.Totals,"shipping")),("id",shippingId.Value),("rut",rut),("address",plan.AddressId!.Value),("weight",plan.Weight),("height",plan.Height),("width",plan.Width),("depth",plan.Depth));}
  var orderId=await RelationalStore.Next(c,tx,"venta","id",ct);await RelationalStore.Exec(c,tx,"INSERT INTO public.venta(id,cliente_id,emprendedor_id,despacho,descripcion) VALUES(@id,@rut,@seller,@shipping,'Venta registrada desde Shopping')",ct,("id",orderId),("rut",rut),("seller",plan.Seller),("shipping",(object?)shippingId??DBNull.Value));
  foreach(var line in plan.Lines.GroupBy(x=>(Id(x),Text(x,"variant")))){var row=line.First()!;var service=Text(row,"type")=="Servicio";var qty=(int)line.Sum(x=>Number(x,"qty"));if(service)await RelationalStore.Exec(c,tx,"INSERT INTO public.contratar(servicio_id,venta_id,cliente_id,emprendedor_id,cantidad,preciounitario,direccion_id) VALUES(@item,@order,@rut,@seller,@qty,0,@address)",ct,("item",(int)Number(row,"dbId")),("order",orderId),("rut",rut),("seller",plan.Seller),("qty",qty),("address",(object?)plan.AddressId??DBNull.Value));else await RelationalStore.Exec(c,tx,"INSERT INTO public.comprar(producto_id,caracteristicas_id,venta_id,cliente_id,emprendedor_id,cantidad,preciounitario) VALUES(@item,@variant,@order,@rut,@seller,@qty,0)",ct,("item",(int)Number(row,"dbId")),("variant",(int)Number(row,"variant")),("order",orderId),("rut",rut),("seller",plan.Seller),("qty",qty));}
  var total=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('total',total)::text FROM public.venta WHERE id=@id",ct,("id",orderId));var paymentId=await RelationalStore.Next(c,tx,"mediopago","id",ct);await RelationalStore.Exec(c,tx,"INSERT INTO public.mediopago(id,cliente_id,tipo,marca,digitos,codigotransferencia) VALUES(@id,@rut,@type,@brand,@last,@reference);INSERT INTO public.vender(venta_id,mediopago_id,monto) VALUES(@order,@id,@total)",ct,("id",paymentId),("rut",rut),("type",request.Payment),("brand",request.Payment=="Tarjeta"?"Tarjeta":""),("last",request.Payment=="Tarjeta"?(object)request.CardLast4!:DBNull.Value),("reference",request.TransferCode??""),("order",orderId),("total",(int)Number(total[0],"total")));
  await RelationalStore.Exec(c,tx,"INSERT INTO shopping_ui.order_events(order_id,status) VALUES(@id,'En preparación')",ct,("id",orderId));
  await RelationalStore.Exec(c,tx,"INSERT INTO shopping_ui.checkout_requests VALUES(@rut,@request,@order)",ct,("rut",rut),("request",request.RequestId),("order",orderId.ToString()));foreach(var quote in quotes)await RelationalStore.Exec(c,tx,"INSERT INTO shopping_ui.used_quotes VALUES(@quote,@order)",ct,("quote",int.Parse(quote)),("order",orderId));
  var savedCart=await RelationalStore.Query(c,tx,"SELECT payload::text FROM shopping_ui.documents WHERE id=@id",ct,("id",Key("cart",rut)));var cart=Rows(savedCart.FirstOrDefault());await state.Save(c,tx,"cart",rut,new JsonArray(cart.Where(x=>Text(x,"seller")!=request.Vendor).Select(x=>x?.DeepClone()).ToArray()),ct);await state.Bump(c,tx,ct);var data=await state.Load(c,tx,ct);var revision=await state.Revision(c,tx,ct);await tx.CommitAsync(ct);return new{order=List(data,"orders").First(o=>Id(o)==orderId.ToString())!.DeepClone(),state=state.Snapshot(data,revision,user)};
 }
}
